package org.springframework.samples.petclinic.rest.advice;

import org.aspectj.lang.annotation.AfterReturning;
import org.aspectj.lang.annotation.Aspect;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.stereotype.Component;

/**
 * Enqueues a welcome notification once an owner is successfully created: emits a line to the
 * dedicated {@code NOTIFY} logger carrying the new owner's id and memberId.
 */
@Aspect
@Component
public class OwnerWelcomeNotifyAdvice {

    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");

    @AfterReturning(pointcut = "execution(* org.springframework.samples.petclinic.rest.controller.v1."
        + "OwnerRestControllerV1.addOwner(..))", returning = "response")
    public void enqueueWelcome(ResponseEntity<?> response) {
        if (response != null && response.getBody() instanceof OwnerDto owner) {
            NOTIFY.info("WELCOME owner={} memberId={}", owner.getId(), owner.getMemberId());
        }
    }
}

